import re, sys
from html.parser import HTMLParser
s = open('/app/index.html').read()

class P(HTMLParser):
    VOID={'meta','br','hr','img','link','input','circle','ellipse','rect','path','polygon','stop','line'}
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.errs=[]; self.ids=set(); self.visible=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if 'id' in d: self.ids.add(d['id'])
        if t not in self.VOID: self.stack.append(t)
    def handle_startendtag(self,t,a): pass
    def handle_endtag(self,t):
        if t in self.VOID: return
        if self.stack and self.stack[-1]==t: self.stack.pop()
        elif t in self.stack:
            while self.stack and self.stack[-1]!=t: self.errs.append('unclosed '+self.stack.pop())
            self.stack.pop()
        else: self.errs.append('stray /'+t)
    def handle_data(self,d):
        if d.strip() and not any(x in self.stack for x in ('style','script','title')):
            # SVG title/desc are non-visual; parser stack for desc/title inside svg: allow if inside svg title/desc
            if 'desc' in self.stack or (self.stack and self.stack[-1] in ('title','desc')): return
            self.visible.append((list(self.stack), d.strip()[:60]))

p=P(); p.feed(s); p.close()
js = re.search(r'<script>(.*?)</script>', s, re.S).group(1)
css = re.search(r'<style>(.*?)</style>', s, re.S).group(1)
js_ids = set(re.findall(r"getElementById\('([^']+)'\)", js))
checks = {
 'tags_balanced': not p.errs and not p.stack,
 'all_js_ids_exist': js_ids <= p.ids,
 'css_braces_balanced': css.count('{')==css.count('}'),
 'js_braces_balanced': js.count('{')==js.count('}') and js.count('(')==js.count(')'),
 'no_external': not re.search(r'https?://|<img|<link|\bsrc=|data:image|@import|url\(', s),
 'reduced_motion_css_and_js': s.count('prefers-reduced-motion')>=2,
 'pointer_handlers': all(k in js for k in ('pointermove','pointerdown','pointerleave')),
 'raf_loop': 'requestAnimationFrame(loop)' in js,
 'canvas_and_svg': '<canvas' in s and '<svg' in s and 'viewBox' in s,
 'responsive': '100svh' in s and '@media (max-width' in s,
 'no_ui_elements': not re.search(r'<button|<nav|<a\s|<h1|<input|<select', s),
 'visible_text_nodes': p.visible,
}
for k,v in checks.items(): print(k, '=>', v)
ok = all(v is True or v==[] for v in checks.values())
print('parser errors:', p.errs, '| unclosed:', p.stack, '| ids:', sorted(p.ids))
print('SMOKE', 'PASS' if ok else 'FAIL')
sys.exit(0 if ok else 1)
